   150	surface_string_id!(
   151	    /// Identifies a *surface* — one client face onto a session (e.g. `gpui:local`).
   152	    SurfaceId
   153	);
   154	surface_string_id!(
   155	    /// Identifies a *canvas* within a surface (e.g. `canvas:main`).
   156	    CanvasId
