     1	//! Daemon connection layer.
     2	//!
     3	//! Single point of contact between the UI and `ocean-daemon`. We speak the
     4	//! product agent API:
     5	//!
     6	//!   POST /v1/agent/turns   → start a turn (returns metadata only)
     7	//!   GET  /v1/agent/events  → SSE stream of AgentTurnEvent
     8	//!   GET  /v1/agent/sessions → list sessions
     9	//!
    10	//! All reply text and tool output arrives as events on the SSE stream; the
    11	//! POST returns once the turn completes but carries no payload beyond
    12	//! turn_id / session_id / status. We push events into a Leptos signal so
    13	//! the rest of the UI reacts naturally.
    14	
    15	use std::collections::VecDeque;
    16	#[cfg(target_arch = "wasm32")]
    17	use std::sync::{Arc, Mutex};
    18	
    19	use futures_util::StreamExt;
    20	use gloo_net::eventsource::futures::EventSource;
    21	use gloo_net::http::Request;
    22	use leptos::prelude::*;
    23	#[cfg(target_arch = "wasm32")]
    24	use send_wrapper::SendWrapper;
    25	use serde::{Deserialize, Serialize};
    26	use serde_json::{json, Value};
    27	use wasm_bindgen::JsCast;
    28	use wasm_bindgen_futures::spawn_local;
