   133	        // `BTreeMap` on `ComponentId`, matching the native id macro's derives.
   134	        #[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Deserialize, Serialize)]
   135	        #[serde(transparent)]
   136	        pub struct $name(pub String);
   137	
   138	        #[allow(dead_code)]
