1558	                                    <span class="ocean-perm__tool">{tool}</span>
1559	                                </div>
1560	                                <div class="ocean-perm__reason">{reason}</div>
1561	                                {has_args.then(|| view! {
1562	                                    <pre class="ocean-perm__args">{args_summary.clone()}</pre>
1563	                                })}
1564	                                <div class="ocean-perm__actions">
1565	                                    <button
1566	                                        class="ocean-perm__deny"
1567	                                        type="button"
1568	                                        disabled=deciding
1569	                                        on:click=move |_| daemon.with_value(|d| {
1570	                                            d.decide_permission(deny_id.clone(), false)
1571	                                        })
1572	                                    >
1573	                                        "Deny"
1574	                                    </button>
